class Solution {
public:
    int openLock(vector<string>& deadends, string target) {
        set<string> seen(deadends.begin(), deadends.end());
        if (seen.count("0000")) return -1;
        queue<string> q;
        q.push("0000");
        seen.insert("0000");
        int turns = 0;
        while (!q.empty()) {
            int sz = q.size();
            for (int k = 0; k < sz; k++) {
                string cur = q.front();
                q.pop();
                if (cur == target) return turns;
                for (int w = 0; w < 4; w++) {
                    for (int d : {1, 9}) {
                        string next = cur;
                        next[w] = '0' + (next[w] - '0' + d) % 10;
                        if (!seen.count(next)) {
                            seen.insert(next);
                            q.push(next);
                        }
                    }
                }
            }
            turns++;
        }
        return -1;
    }
};
